import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void publishedValuesAndRejectedChange(){Object v=TaskBinding.vehicle(2,10,25);assertEquals(250,TaskBinding.range(v));assertEquals(2.0,TaskBinding.fuel(v,50),1e-6);assertThrows(IllegalArgumentException.class,()->TaskBinding.set(v,1,0));assertEquals(250,TaskBinding.range(v));assertThrows(IllegalArgumentException.class,()->TaskBinding.fuel(v,-1));}}
